import networkx as nx
from itertools import combinations
import random

def girth(G):
    try:
        return nx.girth(G)
    except:
        pass
    # manual
    best = float('inf')
    for v in G.nodes():
        # BFS
        dist = {v: 0}
        parent = {v: None}
        from collections import deque
        q = deque([v])
        while q:
            u = q.popleft()
            for w in G.neighbors(u):
                if w not in dist:
                    dist[w] = dist[u]+1
                    parent[w] = u
                    q.append(w)
                elif parent[u] != w:
                    best = min(best, dist[u]+dist[w]+1)
    return best

def chromatic_at_most_4(G):
    # try greedy with many orderings; then verify with exact if needed
    n = G.number_of_nodes()
    # exact via backtracking
    nodes = sorted(G.nodes(), key=lambda x: -G.degree(x))
    color = {}
    adj = {v: list(G.neighbors(v)) for v in G.nodes()}
    def bt(i):
        if i == len(nodes): return True
        v = nodes[i]
        used = {color[u] for u in adj[v] if u in color}
        for c in range(4):
            if c not in used:
                color[v] = c
                if bt(i+1): return True
                del color[v]
        return False
    return bt(0)

