from itertools import combinations
from collections import deque
import random

def girth(adj, n):
    best = float('inf')
    for s in range(n):
        dist = [-1]*n
        parent = [-1]*n
        dist[s] = 0
        q = deque([s])
        while q:
            u = q.popleft()
            for w in adj[u]:
                if dist[w] == -1:
                    dist[w] = dist[u]+1
                    parent[w] = u
                    q.append(w)
                elif parent[u] != w:
                    c = dist[u]+dist[w]+1
                    if c < best: best = c
    return best

def chromatic_at_most_4(adj, n):
    nodes = sorted(range(n), key=lambda x: -len(adj[x]))
    color = [-1]*n
    def bt(i):
        if i == n: return True
        v = nodes[i]
        used = set()
        for u in adj[v]:
            if color[u] != -1:
                used.add(color[u])
        for c in range(4):
            if c not in used:
                color[v] = c
                if bt(i+1): return True
                color[v] = -1
        return False
    return bt(0)

n = 16
random.seed(42)
found = None
for trial in range(500):
    adj = [set() for _ in range(n)]
    edges = set()
    def add(u,v):
        if u>v: u,v=v,u
        edges.add((u,v))
        adj[u].add(v); adj[v].add(u)
    def rem(u,v):
        if u>v: u,v=v,u
        edges.discard((u,v))
        adj[u].discard(v); adj[v].discard(u)
    # start with 16-cycle
    for i in range(n):
        add(i,(i+1)%n)
    possible = [(u,v) for u,v in combinations(range(n),2) if (u,v) not in edges]
    random.shuffle(possible)
    for u,v in possible:
        add(u,v)
        if girth(adj,n) < 8:
            rem(u,v)
    if len(edges) >= 20:
        # adj list
        adj_list = [list(a) for a in adj]
        if chromatic_at_most_4(adj_list, n):
            found = (list(edges), girth(adj_list,n), len(edges))
            break

